"use strict";var qrcode={init:function(){qrcode.hideOtpStatus();var n=$("#qrcodetext").data("qrcodetext"),t=new QRious({element:document.getElementById("setup-otp-qrcode"),padding:null,value:n,size:185});qrcode.setup()},setup:function(){$("#verify-setup-otp-form").on("submit",function(n){n.preventDefault();var t=$(this).serialize();return $.ajax({url:$(this).attr("action"),method:$(this).attr("method"),data:t,success:function(){qrcode.otpSuccess()},error:function(){qrcode.otpFail();var n=$("#verify-setup-otp-form").find("input[name=Otp]");n.val("");n.data("isencrypted",!1)}}),!1})},hideOtpStatus:function(){$("#verify-setup-otp-fail").hide();$("#verify-setup-otp-success").hide()},otpFail:function(){$("#verify-setup-otp-fail").show();$("#verify-setup-otp-success").hide()},otpSuccess:function(){$("#verify-setup-otp-fail").hide();$("#verify-setup-otp-success").show();$("#verify-setup-otp-form > fieldset").prop("disabled",!0);window.setTimeout(qrcode.navigateToVerifyOTP,3e3)},navigateToVerifyOTP:function(){$(location).attr("href","/Account/VerifyOTP")}};$(document).ready(function(){qrcode.init()});